<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({characteristics:[],signals:[]}),msg=ref('');const active=computed(()=>data.value.characteristics.filter(x=>x.status==='ACTIVE').length);async function load(){try{data.value=await request('/api/spc-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/spc-ops/characteristics',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',characteristicCode:'CTQ-'+Date.now(),name:'关键轴径',unit:'mm',targetValue:10,lowerSpecLimit:9.4,upperSpecLimit:10.6,sigma:.1})});msg.value='质量特性已创建，等待启用控制图';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>STATISTICAL PROCESS CONTROL</small><h3>过程稳定性控制中心</h3><p>实时判定越界与连续偏移，通过 CAPA 阻止异常过程继续放行。</p></div><button @click="create">新建质量特性</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>受控特性</span><b>{{active}}</b><small>已启用控制图</small></article><article><span>过程异常</span><b>{{data.signals.length}}</b><small>自动判异信号</small></article><article><span>待验证 CAPA</span><b>{{data.signals.filter(x=>x.status==='READY_VERIFY').length}}</b><small>独立效果验证</small></article></section><section class="board"><article><header><h4>过程能力</h4><button @click="load">刷新</button></header><div class="row" v-for="x in data.characteristics" :key="x.id"><div><b>{{x.name}}</b><small>{{x.characteristicCode}} · Cp {{x.cp}} / Cpk {{x.cpk}}</small></div><em>{{x.status}}</em></div><p v-if="!data.characteristics.length">暂无专业质量特性。</p></article><article><header><h4>判异与纠偏</h4><span>Western Electric</span></header><div class="row" v-for="x in data.signals" :key="x.id"><div><b>{{x.ruleCode}}</b><small>{{x.signalNo}} · {{x.owner||'待分派'}}</small></div><em>{{x.status}}</em></div><p v-if="!data.signals.length">当前没有过程异常信号。</p></article></section></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:end;padding:27px 30px;border-radius:14px;background:#193d45;color:#fff}.head small{color:#9dccd2;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#d0e4e6}.head button{border:0;border-radius:8px;padding:11px 17px;background:#e7b75e;color:#17383f;font-weight:700}.msg{padding:10px 14px;background:#eff9fa;border-left:3px solid #348694}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #dce7e9;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#687d81}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.row{display:flex;justify-content:space-between;align-items:center}.board header{padding-bottom:12px;border-bottom:1px solid #e9eff0}.board header button{border:0;background:transparent;color:#277985}.row{padding:14px 0;border-bottom:1px solid #edf2f2}.row small{display:block;color:#748488;margin-top:4px}.row em{font-size:12px;font-style:normal;color:#29737d}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
